sql.where:
IFNULL(ah.delete_flag, '0') != '1'

    AND ah.bill_time >= #{beginTime}


    AND ah.bill_time <= #{endTime}


    AND ah.bill_no LIKE CONCAT('%', #{billNo}, '%')


    AND ah.organ_id = #{organId}


    AND ah.creator = #{creator}


    AND ah.hands_person_id = #{handsPersonId}


    AND ai.account_id = #{accountId}


    AND ah.type = #{type}


    AND ai.in_out_item_id = #{inOutItemId}


    AND IFNULL(ai.remark, '') LIKE CONCAT('%', #{remark}, '%')

mapper.select:
SELECT ai.id AS id, ah.id AS billId, ah.bill_no AS billNo, ioi.name AS inOutItem, s.supplier AS organName, p.name AS handsPersonName, u.username AS userName, a.name AS accountName, ah.type AS type, ABS(IFNULL(ai.each_amount, 0)) AS eachAmount, ai.remark AS remark, DATE_FORMAT(ah.bill_time, '%Y-%m-%d %H:%i:%s') AS billTime, (SELECT dh.number FROM jsh_depot_head dh WHERE dh.id = ai.bill_id) AS linkNumber FROM jsh_account_item ai INNER JOIN jsh_account_head ah ON ah.id = ai.header_id LEFT JOIN jsh_in_out_item ioi ON ioi.id = ai.in_out_item_id LEFT JOIN jsh_supplier s ON s.id = ah.organ_id LEFT JOIN jsh_person p ON p.id = ah.hands_person_id LEFT JOIN jsh_user u ON u.id = ah.creator LEFT JOIN jsh_account a ON a.id = ai.account_id
ORDER BY ah.bill_time DESC, ai.id DESC
LIMIT #{offset}, #{rows}

