mapper.select:
SELECT ah.id AS id, ah.id AS billId, ah.bill_no AS billNo, ah.bill_no AS billNumber, ah.type AS type, s.supplier AS organName, p.name AS handsPersonName, u.username AS userName, a.name AS accountName, IFNULL((SELECT ROUND(SUM(ABS(IFNULL(ai2.each_amount, 0))), 6) FROM jsh_account_item ai2 WHERE ai2.header_id = ah.id AND IFNULL(ai2.delete_flag, '0') != '1'), 0) AS changeAmount, ah.remark AS remark, DATE_FORMAT(ah.bill_time, '%Y-%m-%d %H:%i:%s') AS billTime FROM jsh_account_head ah LEFT JOIN jsh_supplier s ON s.id = ah.organ_id LEFT JOIN jsh_person p ON p.id = ah.hands_person_id LEFT JOIN jsh_user u ON u.id = ah.creator LEFT JOIN jsh_account a ON a.id = ah.account_id
ORDER BY ah.bill_time DESC, ah.id DESC
LIMIT #{offset}, #{rows}

