mapper.select:
SELECT dh.type AS grpType, dh.sub_type AS grpSubType, IFNULL(dh.pay_type, '') AS grpPayType, IFNULL(SUM(dh.total_price), 0) AS amount FROM jsh_depot_head dh WHERE IFNULL(dh.delete_flag, '0') != '1' AND dh.status = '1'
AND dh.oper_time >= #{beginTime}
AND dh.oper_time <= #{endTime}
AND dh.organ_id = #{organizationId}
GROUP BY dh.type, dh.sub_type, IFNULL(dh.pay_type, '')

SELECT ah.type AS grpType, ah.type AS grpSubType, '' AS grpPayType, IFNULL(SUM(ABS(IFNULL(ai.each_amount, 0))), 0) AS amount FROM jsh_account_head ah INNER JOIN jsh_account_item ai ON ai.header_id = ah.id AND IFNULL(ai.delete_flag, '0') != '1' WHERE IFNULL(ah.delete_flag, '0') != '1' AND ah.status = '1'
AND ah.bill_time >= #{beginTime}
AND ah.bill_time <= #{endTime}
AND ah.organ_id = #{organizationId}
GROUP BY ah.type

