mapper.sql:
SELECT dh.id AS billId, dh.number AS number, 'bill' AS fromType, dh.sub_type AS billType, dh.sales_man AS salesMan, s.supplier AS organName, IFNULL(dh.total_price, 0) AS allPrice, dh.oper_time AS sortTime FROM jsh_depot_head dh LEFT JOIN jsh_supplier s ON s.id = dh.organ_id WHERE IFNULL(dh.delete_flag, '0') != '1' AND dh.status = '1' AND IFNULL(dh.sales_man, '') != ''
AND dh.oper_time >= #{beginTime}
AND dh.oper_time <= #{endTime}
AND dh.sales_man = #{salesMan}
UNION ALL SELECT ah.id AS billId, ah.bill_no AS number, 'financial' AS fromType, ah.type AS billType, '' AS salesMan, s2.supplier AS organName, IFNULL((SELECT ROUND(SUM(ABS(IFNULL(ai2.each_amount, 0))), 6) FROM jsh_account_item ai2 WHERE ai2.header_id = ah.id AND IFNULL(ai2.delete_flag, '0') != '1'), 0) AS allPrice, ah.bill_time AS sortTime FROM jsh_account_head ah LEFT JOIN jsh_supplier s2 ON s2.id = ah.organ_id WHERE IFNULL(ah.delete_flag, '0') != '1' AND ah.status = '1'
AND 1 = 1
AND 1 = 2
AND ah.bill_time >= #{beginTime}
AND ah.bill_time <= #{endTime}

mapper.select:
